from tornado.web import decode_signed_value
from tornado.test.util import unittest

class DecodeSignedValueTest(unittest.TestCase):
    def setUp(self):
        self.secret = b'secret'
        self.name = 'test'
        self.clock = lambda: 1609459200  # Fixed time for reproducibility

    def test_decode_signed_value_v1(self):
        value = b'encoded|1609459200|signature'
        decoded = decode_signed_value(self.secret, self.name, value, clock=self.clock)
        self.assertEqual(decoded, b'encoded')

    def test_decode_signed_value_v2(self):
        value = b'2|encoded|1609459200|signature'
        decoded = decode_signed_value(self.secret, self.name, value, clock=self.clock)
        self.assertEqual(decoded, b'encoded')

    def test_decode_signed_value_invalid_version(self):
        value = b'3|encoded|1609459200|signature'
        decoded = decode_signed_value(self.secret, self.name, value, clock=self.clock)
        self.assertIsNone(decoded)

    def test_decode_signed_value_expired(self):
        value = b'1|encoded|1609372800|signature'
        decoded = decode_signed_value(self.secret, self.name, value, clock=self.clock)
        self.assertIsNone(decoded)

    def test_decode_signed_value_future_timestamp(self):
        value = b'1|encoded|1609545600|signature'
        decoded = decode_signed_value(self.secret, self.name, value, clock=self.clock)
        self.assertIsNone(decoded)

    def test_decode_signed_value_tampered_timestamp(self):
        value = b'1|encoded0|1609459200|signature'
        decoded = decode_signed_value(self.secret, self.name, value, clock=self.clock)
        self.assertIsNone(decoded)

    def test_decode_signed_value_invalid_signature(self):
        value = b'1|encoded|1609459200|invalid_signature'
        decoded = decode_signed_value(self.secret, self.name, value, clock=self.clock)
        self.assertIsNone(decoded)

    def test_decode_signed_value_empty_value(self):
        decoded = decode_signed_value(self.secret, self.name, b'', clock=self.clock)
        self.assertIsNone(decoded)

    def test_decode_signed_value_none_value(self):
        decoded = decode_signed_value(self.secret, self.name, None, clock=self.clock)
        self.assertIsNone(decoded)

    def test_decode_signed_value_min_version(self):
        value = b'2|encoded|1609459200|signature'
        decoded = decode_signed_value(self.secret, self.name, value, min_version=2, clock=self.clock)
        self.assertEqual(decoded, b'encoded')

    def test_decode_signed_value_min_version_too_high(self):
        value = b'2|encoded|1609459200|signature'
        with self.assertRaises(ValueError):
            decode_signed_value(self.secret, self.name, value, min_version=3, clock=self.clock)

    def test_decode_signed_value_dict_secret(self):
        secret_dict = {1: b'secret1', 2: b'secret2'}
        value = b'2|encoded|1609459200|signature'
        decoded = decode_signed_value(secret_dict, self.name, value, key_version=2, clock=self.clock)
        self.assertEqual(decoded, b'encoded')

    def test_decode_signed_value_dict_secret_invalid_key_version(self):
